CREATE OR REPLACE FUNCTION enrichment.metadata_occupation_candidates(ncs text,source jsonb,cap integer DEFAULT 12)
RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE answer jsonb; BEGIN
 IF cap IS NULL OR cap NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_CAP_1_TO_30'; END IF;
 IF NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_catalog_context WHERE ncs_run_id=ncs)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CATALOG_NOT_PREPARED'; END IF;
 WITH input AS (SELECT
  lower((SELECT string_agg(value,' ' ORDER BY key) FROM jsonb_each_text(fields))) AS text,
  lower(concat_ws(' ',fields->>'role',fields->>'title')) AS role_text
  FROM (SELECT enrichment.metadata_occupation_fields(source) AS fields) f),
 words AS MATERIALIZED (
  SELECT DISTINCT word FROM input CROSS JOIN LATERAL regexp_split_to_table(input.text,'[^가-힣a-z0-9]+') word
  WHERE length(word) BETWEEN 2 AND 40
   AND word NOT IN('채용','모집','신입','경력','주니어','시니어','담당','관련','업무','회사','무관','개발자','엔지니어','developer','engineer','engineering','junior','senior')
 ), aliases AS (
  -- Retrieval hints translate common listing role vocabulary to official labels.
  -- They are not evidence and do not create an accepted classification.
  SELECT term,2.5::numeric AS weight FROM input CROSS JOIN LATERAL (VALUES
   ('(백.?엔드|프론트.?엔드|프런트|풀스택|backend|frontend|full.?stack|웹|앱|프로그래머|programmer|바이브|소프트웨어|software|java|python|typescript|javascript|csharp|c#|c\+\+|\.net|react|spring)','응용sw'),
   ('(데이터.?분석|data.?analyst|data.?scientist|데이터.?사이언티스트|빅데이터.?분석)','빅데이터분석'),
   ('(데이터.?엔지니어|data.?engineer|데이터.?플랫폼)','빅데이터플랫폼'),
   ('(데이터베이스|database|dba|sql)','데이터베이스'),
   ('(클라우드|cloud|aws|devops)','it시스템'),
   ('(클라우드|cloud|aws)','클라우드'),
   ('(인공지능|머신러닝|딥러닝|(^|[^a-z])ai([^a-z]|$))','인공지능'),
   ('(머신.?비전|machine.?vision|컴퓨터.?비전|computer.?vision)','영상정보'),
   ('(머신.?비전|machine.?vision|컴퓨터.?비전|computer.?vision)','인공지능'),
   ('(머신.?비전|machine.?vision|컴퓨터.?비전|computer.?vision|설비.?연동)','응용sw'),
   ('(임베디드|embedded|펌웨어|firmware|설비.?연동)','임베디드'),
   ('(iot|사물.?인터넷|설비.?연동|시스템.?통합)','iot'),
   ('(강사|교수|교육|훈련|instructor|lecturer|trainer|teacher)','기술교육'),
   ('(강사|교수|교육|훈련|instructor|lecturer|trainer|teacher)','교수'),
   ('(기계|mechanical|자동화.?장비|자동화.?설비|클린.?자동화)','기계설계'),
   ('(기계|mechanical|자동화.?장비|자동화.?설비|클린.?자동화)','기계요소'),
   ('(정보.?보안|정보.?보호|security|cyber|threat|보안)','정보보호'),
   ('(cyber|threat|보안.?사고|침해.?사고)','보안사고'),
   ('(네트워크|network)','네트워크')) x(pattern,term) WHERE input.text ~ x.pattern
  AND NOT(x.term='정보보호' AND input.role_text ~ '(물리.?보안|physical.?security)'
   AND input.role_text !~ '(정보.?보안|정보.?보호|(^|[^a-z])it([^a-z]|$)|cyber|시스템|네트워크|클라우드)')

  UNION ALL
  SELECT term,2.5::numeric FROM input CROSS JOIN LATERAL (VALUES
   ('(^|[^a-z0-9])(fw|firmware)([^a-z0-9]|$)|펌웨어','임베디드'),
   ('(^|[^a-z0-9])(fw|firmware)([^a-z0-9]|$)|펌웨어','펌웨어'),
   ('(^|[^a-z0-9])qa([^a-z0-9]|$)|quality.?assurance|품질.?보증','품질보증'),
   ('(^|[^a-z0-9])qa([^a-z0-9]|$)|quality.?assurance|품질.?보증','품질관리'),
   ('(^|[^a-z0-9])qa([^a-z0-9]|$)|software.?test|test.?engineer|소프트웨어.?테스트|테스트.?엔지니어|테스터','it테스트'),
   ('(outsystems|아웃시스템즈).*(개발|developer|development)|(개발|developer|development).*(outsystems|아웃시스템즈)|사이트.*개발|개발.*사이트|정보보안.*개발자','응용sw'),
   ('(windows|linux|서버|포탈|포털|전산|네트워크).*(admin|운영|관리|유지보수)|(admin|운영|관리|유지보수).*(windows|linux|서버|포탈|포털|전산|네트워크)|sysadmin|system.?administrator|시스템.?관리자','it시스템'),
   ('(sap|erp|정보기술|클라우드|software|소프트웨어).*(컨설턴트|컨설팅|consultant|consulting)|(컨설턴트|컨설팅|consultant|consulting).*(sap|erp|정보기술|클라우드|software|소프트웨어)','정보기술컨설팅'),
   ('(sap|erp|정보기술|클라우드|software|소프트웨어).*(^|[^a-z])pm([^a-z]|$)|(sap|erp|정보기술|클라우드|software|소프트웨어).*프로젝트.*관리','it프로젝트'),
   ('(네트워크|network).*(엔지니어|engineer)|(엔지니어|engineer).*(네트워크|network)','nw엔지니어링'),
   ('compiler|컴파일러','시스템sw'),
   ('compiler|컴파일러','컴파일러'),
   ('(물리.?보안|physical.?security|경비)','경비'),
   ('customer.?success|고객.?성공','고객관리'),
   ('customer.?success|고객.?성공','영업')
  ) roles(pattern,term) WHERE input.role_text ~ roles.pattern
 ), terms AS MATERIALIZED (
  SELECT term,max(weight) AS weight FROM (
   SELECT word AS term,1.0::numeric AS weight FROM words
   UNION ALL SELECT substring(word FROM pos FOR len),CASE WHEN len=3 THEN 0.4 ELSE 0.15 END
   FROM words CROSS JOIN generate_series(2,3) len CROSS JOIN LATERAL generate_series(1,length(word)-len+1) pos
   WHERE word ~ '^[가-힣]+$' AND length(word)>len
   UNION ALL SELECT term,weight FROM aliases
  ) fragments WHERE term NOT IN('채용','모집','신입','경력','담당','업무','관련','회사','개발','관리','운영','지원')
  GROUP BY term ORDER BY max(weight) DESC,length(term) DESC,term LIMIT 60
 ), hits AS MATERIALIZED (
  SELECT c.occupation_code,t.term,t.weight,
   CASE WHEN position(t.term in lower(c.occupation_name))>0 THEN 8.0 ELSE 1.0 END AS location_weight
  FROM enrichment.metadata_occupation_catalog c JOIN terms t ON position(t.term in c.search_text)>0
  WHERE c.ncs_run_id=ncs
 ), frequency AS (SELECT term,count(*) AS count FROM hits GROUP BY term),
 ranked AS (
  SELECT h.occupation_code,sum(h.weight*h.location_weight*ln(1.0+
   (SELECT count(*) FROM enrichment.metadata_occupation_catalog WHERE ncs_run_id=ncs)::numeric/f.count)) AS score
  FROM hits h JOIN frequency f USING(term) GROUP BY h.occupation_code
  ORDER BY score DESC,h.occupation_code LIMIT cap
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('occupation_code',c.occupation_code,
  'occupation_name',c.occupation_name,'classification_names',k.classification_names,
  'unit_names',c.unit_names,'catalog_hash',k.context_hash,'retrieval_score',round(r.score,3)) ORDER BY r.score DESC,c.occupation_code),'[]')
 INTO answer FROM ranked r JOIN enrichment.metadata_occupation_catalog c USING(occupation_code)
 JOIN enrichment.metadata_occupation_catalog_context k ON k.ncs_run_id=c.ncs_run_id AND k.occupation_code=c.occupation_code
 WHERE c.ncs_run_id=ncs;
 RETURN answer;
END $$;

CREATE OR REPLACE FUNCTION enrichment.bind_metadata_occupation_item(id text,bundle text,candidates jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE i enrichment.item%ROWTYPE; b enrichment.batch%ROWTYPE; ib enrichment.input_bundle%ROWTYPE;
 old enrichment.metadata_occupation_binding%ROWTYPE; metadata text; ch text; bh text; candidate jsonb; expected jsonb;
BEGIN
 PERFORM retention.gate();
 SELECT * INTO STRICT i FROM enrichment.item WHERE item_id=id FOR UPDATE;
 SELECT * INTO STRICT b FROM enrichment.batch WHERE batch_id=i.batch_id;
 SELECT * INTO STRICT ib FROM enrichment.input_bundle WHERE bundle_id=bundle;
 PERFORM enrichment.verify_item_input(id);
 IF b.mode<>'ENRICH' OR b.settings->>'metadata_scope' IS DISTINCT FROM 'NCS_OCCUPATION_INFERENCE_V1'
  OR b.settings->>'acceptance_policy' IS DISTINCT FROM 'REVIEW'
  OR coalesce(b.settings->>'prompt_version','') NOT IN ('ko-metadata-occupation-v1','ko-metadata-occupation-v2')
  OR ib.job_run_id<>b.job_run_id OR ib.posting_id<>i.posting_id OR ib.source_hash<>i.source_hash
  OR ib.source_data<>i.source_data OR ib.source_data#>>'{_input,contract}' IS DISTINCT FROM 'jobkorea-input-v1'
  OR NOT EXISTS(SELECT 1 FROM enrichment.item_input WHERE item_id=id AND bundle_id=bundle)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='jobkorea' AND run_id=b.job_run_id)
  OR NOT EXISTS(SELECT 1 FROM ingestion.latest_ready_run WHERE source_id='ncs_competency' AND run_id=b.ncs_run_id)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_INPUT_BINDING_INVALID'; END IF;
 IF jsonb_typeof(candidates) IS DISTINCT FROM 'array' OR jsonb_array_length(candidates)>30
  OR jsonb_array_length(candidates)<>(SELECT count(DISTINCT x->>'occupation_code') FROM jsonb_array_elements(candidates) x)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATES_INVALID'; END IF;
 metadata:=enrichment.hash(enrichment.metadata_occupation_fields(i.source_data)::text);
 ch:=enrichment.hash(candidates::text);
 bh:=enrichment.hash(jsonb_build_array('metadata-occupation-binding-v1',b.job_run_id,b.ncs_run_id,bundle,i.source_hash,metadata,ch)::text);
 SELECT * INTO old FROM enrichment.metadata_occupation_binding WHERE item_id=id;
 IF FOUND THEN
  -- Existing items replay their original context exactly, including the five
  -- pre-correction paid results; never reinterpret them against the new view.
  IF old.candidates<>candidates THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_CHANGED'; END IF;
  IF old.bundle_id<>bundle OR old.binding_hash<>bh OR old.source_hash<>i.source_hash
   OR old.metadata_hash<>metadata OR old.candidates_hash<>ch
  THEN RAISE EXCEPTION 'METADATA_OCCUPATION_BINDING_CHANGED'; END IF;
  RETURN jsonb_build_object('item_id',id,'bundle_id',bundle,'source_hash',i.source_hash,
   'metadata_hash',metadata,'candidates_hash',ch,'binding_hash',bh);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_catalog_context
  WHERE ncs_run_id=b.ncs_run_id AND catalog_context_hash=b.ncs_hash)
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_BATCH_CONTEXT_CHANGED'; END IF;
 FOR candidate IN SELECT value FROM jsonb_array_elements(candidates) LOOP
  SELECT jsonb_build_object('occupation_code',c.occupation_code,'occupation_name',c.occupation_name,
   'classification_names',k.classification_names,'unit_names',c.unit_names,'catalog_hash',k.context_hash)
  INTO expected FROM enrichment.metadata_occupation_catalog c
  JOIN enrichment.metadata_occupation_catalog_context k USING(ncs_run_id,occupation_code)
  WHERE c.ncs_run_id=b.ncs_run_id AND c.occupation_code=candidate->>'occupation_code';
  IF expected IS NULL OR candidate-'retrieval_score'<>expected
  THEN RAISE EXCEPTION 'METADATA_OCCUPATION_CANDIDATE_CHANGED'; END IF;
 END LOOP;
 INSERT INTO enrichment.metadata_occupation_binding(item_id,bundle_id,job_run_id,ncs_run_id,source_hash,metadata_hash,candidates,candidates_hash,binding_hash)
 VALUES(id,bundle,b.job_run_id,b.ncs_run_id,i.source_hash,metadata,candidates,ch,bh) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('item_id',id,'bundle_id',bundle,'source_hash',i.source_hash,
  'metadata_hash',metadata,'candidates_hash',ch,'binding_hash',bh);
END $$;

CREATE OR REPLACE FUNCTION enrichment.plan_metadata_occupation_batch(id text,jobs text,ncs text,opts jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE j text; n text; nh text; plan_settings jsonb; selected text[]; source record;
 i text; a text; candidates jsonb; binding jsonb; data jsonb; request jsonb; schema jsonb;
 p enrichment.prompt%ROWTYPE; cache text; reused text; status text; ordinal integer:=0; catalog jsonb; requested_prompt text:=coalesce(opts->>'prompt_version','ko-metadata-occupation-v1');
BEGIN
 PERFORM retention.gate();
 IF requested_prompt NOT IN ('ko-metadata-occupation-v1','ko-metadata-occupation-v2') THEN RAISE EXCEPTION 'INVALID_METADATA_PROMPT_VERSION'; END IF;
 IF id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$' OR jsonb_typeof(opts) IS DISTINCT FROM 'object' OR
 NOT opts ?& ARRAY['categorize_model','extra_params','limit','candidate_limit','max_matches',
 'max_input_chars','max_output_tokens','max_requests','request_reserve_usd','max_cost_usd','daily_budget_usd',
 'request_delay_ms','read_timeout_ms','execute_requests','reuse_cache','endpoint'] OR
 (opts->>'limit')::integer NOT BETWEEN 1 AND 10000 OR
 (opts->>'candidate_limit')::integer NOT BETWEEN 1 AND 30 OR
 (opts->>'max_matches')::integer NOT BETWEEN 1 AND 2 OR
 (opts->>'max_input_chars')::integer NOT BETWEEN 1000 AND 100000 OR
 (opts->>'max_output_tokens')::integer NOT BETWEEN 256 AND 2048 OR
 (opts->>'max_requests')::integer NOT BETWEEN 1 AND 10000 OR
 (opts->>'request_reserve_usd')::numeric NOT BETWEEN 0.001 AND 1 OR
 (opts->>'max_cost_usd')::numeric NOT BETWEEN 0.001 AND 50 OR
 (opts->>'daily_budget_usd')::numeric NOT BETWEEN 0.001 AND 50 OR
 (opts->>'request_delay_ms')::integer NOT BETWEEN 0 AND 60000 OR
 (opts->>'read_timeout_ms')::integer NOT BETWEEN 1000 AND 600000 OR
 opts->>'execute_requests' NOT IN ('Y','N') OR opts->>'reuse_cache' NOT IN ('Y','N') OR
 nullif(opts->>'categorize_model','') IS NULL OR
 (opts->>'endpoint' IS DISTINCT FROM 'https://openrouter.ai/api/v1/chat/completions' AND
  NOT(coalesce(current_setting('jobtology.isolated_fixture',true),'') ~ '^[0-9a-f]{12}$' AND
   opts->>'endpoint' ~ ('^http://jobtology-jobkorea-test-'||current_setting('jobtology.isolated_fixture',true)||'-mock:[0-9]{1,5}/chat/completions$')
   AND opts->>'categorize_model'='fixture/metadata'))
 THEN RAISE EXCEPTION 'INVALID_METADATA_OCCUPATION_OPTIONS'; END IF;
 IF opts->>'endpoint'='https://openrouter.ai/api/v1/chat/completions' AND
  (opts->>'categorize_model' IS DISTINCT FROM 'openai/gpt-5.6-luna' OR opts->>'provider_only' IS DISTINCT FROM 'openai')
 THEN RAISE EXCEPTION 'METADATA_OCCUPATION_REQUIRES_PRICED_MODEL_AND_PROVIDER'; END IF;
 IF opts->>'temperature' IS NOT NULL AND (opts->>'temperature')::numeric NOT BETWEEN 0 AND 2
 THEN RAISE EXCEPTION 'INVALID_TEMPERATURE'; END IF;
 IF opts->>'reasoning_effort' IS NOT NULL AND opts->>'reasoning_effort' NOT IN ('none','minimal','low','medium','high')
 THEN RAISE EXCEPTION 'INVALID_REASONING_EFFORT'; END IF;
 IF opts ? 'provider_only' AND (jsonb_typeof(opts->'provider_only') IS DISTINCT FROM 'string' OR
  opts->>'provider_only' !~ '^[a-z0-9][a-z0-9_./-]{0,127}$')
 THEN RAISE EXCEPTION 'INVALID_PROVIDER_SLUG'; END IF;
 IF jsonb_typeof(opts->'extra_params') IS DISTINCT FROM 'object' OR EXISTS(
 SELECT 1 FROM jsonb_object_keys(opts->'extra_params') k WHERE k NOT IN ('top_p','seed','frequency_penalty','presence_penalty')) OR
 EXISTS(SELECT 1 FROM jsonb_each(opts->'extra_params') WHERE jsonb_typeof(value)<>'number') OR
 coalesce((opts#>>'{extra_params,top_p}')::numeric,1) NOT BETWEEN 0 AND 1 OR
 coalesce((opts#>>'{extra_params,frequency_penalty}')::numeric,0) NOT BETWEEN -2 AND 2 OR
 coalesce((opts#>>'{extra_params,presence_penalty}')::numeric,0) NOT BETWEEN -2 AND 2
 THEN RAISE EXCEPTION 'INVALID_EXTRA_PARAMS'; END IF;
 IF nullif(opts->>'posting_ids','') IS NOT NULL THEN
  selected:=string_to_array(opts->>'posting_ids','|');
  IF cardinality(selected)=0 OR cardinality(selected)>(opts->>'limit')::integer OR
   cardinality(selected)<>(SELECT count(DISTINCT v) FROM unnest(selected) v) OR
   EXISTS(SELECT 1 FROM unnest(selected) v WHERE v !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$')
  THEN RAISE EXCEPTION 'INVALID_POSTING_SELECTION'; END IF;
 END IF;
 j:=enrichment.resolve_snapshot(jobs,'jobkorea'); n:=enrichment.resolve_snapshot(ncs,'ncs_competency');
 catalog:=enrichment.prepare_metadata_occupation_catalog(n);
 nh:=catalog->>'catalog_hash';
 IF nh IS NULL THEN RAISE EXCEPTION 'EMPTY_NCS_CATALOG'; END IF;
 plan_settings:=opts||jsonb_build_object('metadata_scope','NCS_OCCUPATION_INFERENCE_V1','prompt_version',requested_prompt,
  'job_source_id','jobkorea','extract_model','unused/metadata-only','acceptance_policy','REVIEW');
 PERFORM pg_advisory_xact_lock(hashtextextended('metadata-occupation-batch:'||id,0));
 IF EXISTS(SELECT 1 FROM enrichment.batch WHERE batch_id=id) THEN
  IF NOT EXISTS(SELECT 1 FROM enrichment.batch existing WHERE existing.batch_id=id AND existing.job_run_id=j AND existing.ncs_run_id=n AND existing.settings=plan_settings)
  THEN RAISE EXCEPTION 'METADATA_BATCH_IS_IMMUTABLE'; END IF;
  RETURN jsonb_build_object('batch_id',id,'job_run_id',j,'ncs_run_id',n,'replay',true);
 END IF;
 SELECT * INTO STRICT p FROM enrichment.prompt WHERE version=requested_prompt AND stage='categorize';
 INSERT INTO enrichment.batch(batch_id,mode,job_run_id,ncs_run_id,ncs_hash,settings,state)
 VALUES(id,'ENRICH',j,n,nh,plan_settings,CASE WHEN opts->>'execute_requests'='Y' THEN 'RUNNING' ELSE 'PLANNED' END);
 FOR source IN SELECT DISTINCT ON (b.posting_id) b.* FROM enrichment.input_bundle b
 WHERE b.job_run_id=j AND b.source_data#>>'{_input,contract}'='jobkorea-input-v1'
 AND (selected IS NULL OR b.posting_id=ANY(selected))
 AND (selected IS NOT NULL OR NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_binding prior
  JOIN enrichment.item old ON old.item_id=prior.item_id
  JOIN enrichment.attempt oa ON oa.attempt_id=old.categorization_id
  WHERE prior.job_run_id=j AND prior.ncs_run_id=n AND old.posting_id=b.posting_id AND prior.source_hash=b.source_hash
  AND (oa.state IN ('VALIDATED','SKIPPED') OR oa.reserved_at IS NOT NULL)))
 ORDER BY b.posting_id,b.created_at,b.bundle_id LIMIT (opts->>'limit')::integer LOOP
  PERFORM enrichment.verify_input_bundle(source.bundle_id);
  ordinal:=ordinal+1; i:=gen_random_uuid()::text; a:=gen_random_uuid()::text;
  INSERT INTO enrichment.item(item_id,batch_id,posting_id,source_data,source_hash,ordinal)
  VALUES(i,id,source.posting_id,source.source_data,source.source_hash,ordinal);
  INSERT INTO enrichment.item_input(item_id,bundle_id) VALUES(i,source.bundle_id);
  candidates:=enrichment.metadata_occupation_candidates(n,source.source_data,(opts->>'candidate_limit')::integer);
  binding:=enrichment.bind_metadata_occupation_item(i,source.bundle_id,candidates);
  schema:=p.output_schema;
  schema:=jsonb_set(schema,'{properties,matches,maxItems}',to_jsonb((opts->>'max_matches')::integer));
  IF jsonb_array_length(candidates)>0 THEN
   schema:=jsonb_set(schema,'{properties,matches,items,properties,occupation_code}',jsonb_build_object('type','string','enum',
    (SELECT jsonb_agg(c->'occupation_code') FROM jsonb_array_elements(candidates) c)));
  ELSE schema:=jsonb_set(schema,'{properties,matches,maxItems}','0'); END IF;
  data:=jsonb_build_object('metadata',enrichment.metadata_occupation_fields(source.source_data),
   'candidates',(SELECT coalesce(jsonb_agg(jsonb_build_object('occupation_code',c->'occupation_code',
    'occupation_name',c->'occupation_name','classification_names',c->'classification_names',
    'representative_unit_names',(SELECT coalesce(jsonb_agg(u.value ORDER BY u.ordinal),'[]')
     FROM jsonb_array_elements(c->'unit_names') WITH ORDINALITY u(value,ordinal) WHERE u.ordinal<=3))),'[]')
    FROM jsonb_array_elements(candidates) c),
   'max_matches',(opts->>'max_matches')::integer);
  request:=jsonb_build_object('model',opts->>'categorize_model','messages',jsonb_build_array(
   jsonb_build_object('role','system','content',p.system_prompt),jsonb_build_object('role','user','content',data::text)),
   'response_format',jsonb_build_object('type','json_schema','json_schema',jsonb_build_object('name','jobtology_metadata_occupation','strict',true,'schema',schema)),
   'provider',jsonb_build_object('require_parameters',true,'allow_fallbacks',false,
    'max_price',jsonb_build_object('prompt',0.20,'completion',1.20)),
   'max_tokens',(opts->>'max_output_tokens')::integer,'stream',false)
   || (opts->'extra_params');
  IF opts->>'provider_only' IS NOT NULL THEN request:=jsonb_set(request,'{provider,only}',jsonb_build_array(opts->>'provider_only')); END IF;
  IF opts->>'temperature' IS NOT NULL THEN request:=request||jsonb_build_object('temperature',(opts->>'temperature')::numeric); END IF;
  IF opts->>'reasoning_effort' IS NOT NULL THEN request:=request||jsonb_build_object('reasoning',jsonb_build_object('effort',opts->>'reasoning_effort','exclude',true)); END IF;
  cache:=enrichment.hash(jsonb_build_object('request',request,'prompt_hash',p.content_hash,'endpoint',opts->>'endpoint',
   'metadata_hash',binding->>'metadata_hash','candidates_hash',binding->>'candidates_hash',
   'ncs_hash',nh,'validator','metadata-occupation-v1','retriever',CASE WHEN requested_prompt='ko-metadata-occupation-v1' THEN 'metadata-occupation-lexical-v1' ELSE 'metadata-occupation-lexical-v2' END)::text);
  reused:=NULL;
  IF opts->>'reuse_cache'='Y' THEN
   SELECT old.attempt_id INTO reused FROM enrichment.attempt old JOIN enrichment.batch ob ON ob.batch_id=old.batch_id
   WHERE old.cache_key=cache AND (old.state='VALIDATED' OR (old.batch_id=id AND old.state='PLANNED'))
   AND ob.settings->>'metadata_scope'='NCS_OCCUPATION_INFERENCE_V1'
   AND NOT EXISTS(SELECT 1 FROM enrichment.metadata_occupation_result r
    JOIN LATERAL(SELECT decision FROM enrichment.metadata_occupation_decision d WHERE d.result_id=r.result_id ORDER BY decision_id DESC LIMIT 1) d ON true
    WHERE r.attempt_id=old.attempt_id AND d.decision='REJECT')
   ORDER BY old.completed_at DESC,old.attempt_id LIMIT 1;
  END IF;
  IF reused IS NOT NULL THEN a:=reused;
  ELSE
   status:=CASE WHEN jsonb_array_length(candidates)=0 THEN 'SKIPPED' ELSE 'PLANNED' END;
   request:=request||jsonb_build_object('session_id',id,'trace',jsonb_build_object('trace_id',replace(i,'-',''),
    'trace_name','JobKorea inferred occupation','span_name','metadata_occupation','environment','staging',
    'release',requested_prompt,'posting_id',source.posting_id,'batch_id',id,'attempt_id',a,
    'job_run_id',j,'ncs_run_id',n,'source_bundle_id',source.bundle_id,'binding_hash',binding->>'binding_hash'));
   IF status<>'SKIPPED' AND (length(request::text)>(opts->>'max_input_chars')::integer OR octet_length(request::text)+256>=272000 OR
    1.05*(0.25*(octet_length(request::text)+256)+1.20*(opts->>'max_output_tokens')::integer)/1000000
     >(opts->>'request_reserve_usd')::numeric) THEN status:='REJECTED'; END IF;
   INSERT INTO enrichment.attempt(attempt_id,batch_id,item_id,stage,cache_key,request_body,candidates,state,parsed_output,issues,completed_at)
   VALUES(a,id,i,'categorize',cache,request,candidates,status,
    CASE WHEN status='SKIPPED' THEN jsonb_build_object('outcome','abstained','matches','[]'::jsonb,'abstain_reason','No occupation candidates retrieved from supplied metadata.') END,
    CASE WHEN status='SKIPPED' THEN '["NO_METADATA_OCCUPATION_CANDIDATES"]'::jsonb WHEN status='REJECTED' THEN '["INPUT_OR_COST_BOUND_EXCEEDED"]'::jsonb ELSE '[]'::jsonb END,
    CASE WHEN status IN ('SKIPPED','REJECTED') THEN clock_timestamp() END);
  END IF;
  UPDATE enrichment.item SET categorization_id=a WHERE item_id=i;
 END LOOP;
 IF selected IS NOT NULL AND ordinal<>cardinality(selected) THEN RAISE EXCEPTION 'INCOMPLETE_FROZEN_METADATA_SELECTION'; END IF;
 RETURN jsonb_build_object('batch_id',id,'job_run_id',j,'ncs_run_id',n,'postings',ordinal,'metadata_scope','NCS_OCCUPATION_INFERENCE_V1',
  'planned_requests',(SELECT count(*) FROM enrichment.attempt WHERE batch_id=id AND state='PLANNED'),
  'no_candidate_abstentions',(SELECT count(*) FROM enrichment.attempt WHERE batch_id=id AND state='SKIPPED'));
END $$;
COMMIT;
